class NetworkChanges {static int next;static String snapshotId(){String s=Integer.toHexString(++next);StringBuilder b=new StringBuilder("a".repeat(32-s.length()));for(char c:s.toCharArray())b.append("abcdefghijklmnop".charAt(Character.digit(c,16)));return b.toString();}static boolean identityMatches(JSONObject record,JSONObject identity){return true;}static JSONObject intent(JSONObject o){return o.optJSONObject("environmentIntent");}static boolean snapshotSlot(String s){return s.matches("pending-(entry|exit)-subscription-[a-p]{32}");}}
class NetworkSourceSelection {static final Object activeLock=new Object();static Runnable beforeLease;static JSONObject byName(JSONObject source,String name){return source.optJSONObject("detail");}interface Action<T>{T run()throws Exception;}static <T>T withActiveSnapshot(Context c,Action<T> a)throws Exception{Runnable hook=beforeLease;beforeLease=null;if(hook!=null)hook.run();synchronized(activeLock){return a.run();}}}
